sp_page.css:
/* General layout padding */
section.page, main.body {
  padding: 20px !important;
  margin: 0 auto;
  max-width: 1200px;
}

/* Spacing between containers/sections */
section.page > div,
main.body > div {
  margin-bottom: 24px;
  padding: 16px;
  background-color: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
}

/* Breadcrumb styling */
nav.breadcrumb {
  font-size: 14px;
  margin-bottom: 20px;
  color: #666;
}
nav.breadcrumb a {
  color: #337ab7;
  text-decoration: none;
}
nav.breadcrumb a:hover {
  text-decoration: underline;
}
nav.breadcrumb .active {
  color: #333;
  font-weight: bold;
}

/* Tab header spacing */
.nav-tabs {
  margin-top: 20px;
  margin-bottom: 16px;
}

/* Headings */
h3, h4, h5 {
  margin-top: 0;
  margin-bottom: 16px;
}
